Database.Load:
var sqlStmt = "SELECT ";
sqlStmt += "Account.Id AS pKey, ";
sqlStmt += "Account.Name AS name ";
sqlStmt += "FROM Account ";
sqlStmt += " JOIN ";
sqlStmt += " RecordType";
sqlStmt += " ON Account.RecordTypeId = RecordType.Id ";                    
sqlStmt += " AND RecordType.DeveloperName = 'Instituciones_sin_venta' ";
return Utils.replaceMacrosParam(sqlStmt);
